var g singleflight.Group

func GetUser(ctx context.Context, id string) (*User, error) {
    k := keyFor(ctx, "user", id)                  // tenant + scope in the key
    v, err, _ := g.Do(k, func() (any, error) {
        return db.LoadUser(ctx, id)               // one in-flight call per key
    })
    if err != nil {
        return nil, err
    }
    return v.(*User), nil
}
